// =============================================================================
// dds_template_library_dialog.dart
//
// Unified DSF Master Template & Generative Products Library:
// 1. Tab 1: 📁 Stored DSF Files (Genuine .dsf files scanned from disk / assets).
// 2. Tab 2: ⚙️ Auto-Generated Products (Procedural Cable Ladder & Fittings Engine).
//
// Dual Studio Integration:
// - TDS Studio: Append to submittal sheet or edit parameters in TDS.
// - CAD Studio: Instant instantiation into 2D/3D editor.
// - Closed loop: Save generative assemblies as permanent DSF templates in Library.
// =============================================================================

import 'package:flutter/material.dart';

import '../../../models/dsf_document.dart';
import '../../../models/dds/dds_document.dart';
import '../../../models/dds/dds_product_instance.dart';
import '../../../models/ladder/ladder_assembly_models.dart';
import '../../../models/ladder/ladder_assembly_parameters.dart';
import '../../../viewmodels/sheet_metal_studio_viewmodel.dart';
import '../../../engine/dds/dds_template_resolver.dart';
import '../../../engine/dds/dsf_library_service.dart';
import '../../../engine/ladder/ladder_assembly_generator.dart';
import 'dds_drawing_painters.dart';

enum DdsLibraryTab {
  storedDsf,
  autoGenerated,
}

class _GenerativePreset {
  final String id;
  final String title;
  final String category;
  final String componentType;
  final String fittingType;
  final String subtitle;
  final String description;
  final IconData icon;

  const _GenerativePreset({
    required this.id,
    required this.title,
    required this.category,
    required this.componentType,
    required this.fittingType,
    required this.subtitle,
    required this.description,
    required this.icon,
  });
}

class DdsTemplateLibraryDialog extends StatefulWidget {
  final DdsDocument? activeDocument;
  final SheetMetalStudioViewModel? viewModel;
  final void Function(DdsProductInstance newInstance, {bool switchToEditor})? onAddToDds;
  final void Function(DsfDocument dsfDocument)? onOpenInEditor;

  const DdsTemplateLibraryDialog({
    super.key,
    this.activeDocument,
    this.viewModel,
    this.onAddToDds,
    this.onOpenInEditor,
  });

  /// Displays the unified template library dialog for TDS or CAD Studio.
  static Future<void> show(
    BuildContext context, {
    DdsDocument? activeDocument,
    SheetMetalStudioViewModel? viewModel,
    void Function(DdsProductInstance newInstance, {bool switchToEditor})? onAddToDds,
    void Function(DsfDocument dsfDocument)? onOpenInEditor,
  }) {
    return showDialog(
      context: context,
      barrierColor: Colors.black.withValues(alpha: 0.5),
      builder: (ctx) => Dialog(
        backgroundColor: Colors.transparent,
        insetPadding: const EdgeInsets.symmetric(horizontal: 24.0, vertical: 24.0),
        child: DdsTemplateLibraryDialog(
          activeDocument: activeDocument,
          viewModel: viewModel,
          onAddToDds: onAddToDds,
          onOpenInEditor: onOpenInEditor,
        ),
      ),
    );
  }

  @override
  State<DdsTemplateLibraryDialog> createState() => _DdsTemplateLibraryDialogState();
}

class _DdsTemplateLibraryDialogState extends State<DdsTemplateLibraryDialog> {
  // Navigation & Tabs
  DdsLibraryTab _currentTab = DdsLibraryTab.storedDsf;

  // Stored DSF State
  List<DsfLibraryItem> _items = [];
  bool _isLoading = true;
  String _searchQuery = '';

  // Filtering Hierarchy
  String _selectedSystemCategory = 'All Categories';
  String _selectedComponentType = 'All Types';
  String _selectedFittingType = 'All Accessories';

  final List<String> _systemCategories = [
    'All Categories',
    'Cable Ladders',
    'Cable Trays',
    'Cable Trunking',
  ];

  final List<String> _componentTypes = [
    'All Types',
    'Straight Lengths',
    'Fittings & Accessories',
  ];

  final List<String> _fittingTypes = [
    'All Accessories',
    'Flat Bends & Elbows',
    'Vertical Risers',
    'Tees & Branches',
    'Crosses & 4-Ways',
    'Reducers & Transitions',
  ];

  // Auto-Generated Ladder Engine State
  late List<_GenerativePreset> _generativePresets;
  late _GenerativePreset _selectedPreset;

  double _genWidth = 300.0;
  double _genHeight = 100.0;
  double _genLength = 3000.0;
  double _genThickness = 2.0;
  double _genRadius = 300.0;
  double _genMinorWidth = 150.0;
  final double _genFlangeWidth = 20.0;
  final LadderFlangeDirection _genFlangeDir = LadderFlangeDirection.inside;
  LadderRungJointMethod _genJointMethod = LadderRungJointMethod.passThroughOutsideWeld;
  final double _genOutsideProjection = 5.0;
  double _genEndMarginPitch = 100.0;
  double _genTargetPitch = 300.0;
  bool _genCustomPitch = false;
  LadderAccessoryStyle _genAccessoryStyle = LadderAccessoryStyle.segmented;

  DsfLadderAssembly? _currentAssembly;
  double _orbitAzimuth = 45.0;
  double _orbitElevation = 35.264;
  bool _isSavingDsf = false;

  @override
  void initState() {
    super.initState();
    _initGenerativePresets();
    _loadTemplates();
    _recomputeGenerativeAssembly();
  }

  void _initGenerativePresets() {
    _generativePresets = [
      const _GenerativePreset(
        id: 'ladder_straight',
        title: 'Cable Ladder Straight (3000mm)',
        category: 'Cable Ladders',
        componentType: 'Straight Lengths',
        fittingType: 'Straight Lengths',
        subtitle: 'Continuous dual-pitch rung run',
        description: 'Standard 3000mm straight run with customizable length, width, and dual-pitch spacing.',
        icon: Icons.view_headline,
      ),
      const _GenerativePreset(
        id: 'ladder_bend_90',
        title: 'Cable Ladder 90° Horizontal Bend',
        category: 'Cable Ladders',
        componentType: 'Fittings & Accessories',
        fittingType: 'Flat Bends & Elbows',
        subtitle: '90° Flat bend (R300 standard)',
        description: 'Right-angle flat bend with circular arc rails and tangential rungs connecting flanges.',
        icon: Icons.turn_right,
      ),
      const _GenerativePreset(
        id: 'ladder_bend_45',
        title: 'Cable Ladder 45° Horizontal Bend',
        category: 'Cable Ladders',
        componentType: 'Fittings & Accessories',
        fittingType: 'Flat Bends & Elbows',
        subtitle: '45° Flat bend (R300 standard)',
        description: '45-degree directional offset fitting with smooth continuous side rail sweep.',
        icon: Icons.turn_slight_right,
      ),
      const _GenerativePreset(
        id: 'ladder_inside_riser_90',
        title: 'Cable Ladder 90° Inside Riser',
        category: 'Cable Ladders',
        componentType: 'Fittings & Accessories',
        fittingType: 'Vertical Risers',
        subtitle: '90° Inside upward riser (R300)',
        description: 'Internal vertical rise with curved web rails for smooth vertical cable transitions.',
        icon: Icons.upgrade,
      ),
      const _GenerativePreset(
        id: 'ladder_outside_riser_90',
        title: 'Cable Ladder 90° Outside Riser',
        category: 'Cable Ladders',
        componentType: 'Fittings & Accessories',
        fittingType: 'Vertical Risers',
        subtitle: '90° Outside downward riser (R300)',
        description: 'External vertical drop fitting with arched side rails maintaining cable bend radius.',
        icon: Icons.vertical_align_bottom,
      ),
      const _GenerativePreset(
        id: 'ladder_reducer',
        title: 'Cable Ladder Concentric Reducer',
        category: 'Cable Ladders',
        componentType: 'Fittings & Accessories',
        fittingType: 'Reducers & Transitions',
        subtitle: 'Symmetric width transition (W1 → W2)',
        description: 'Straight tapered reducer with angled side walls and varying rung cut lengths.',
        icon: Icons.compress,
      ),
      const _GenerativePreset(
        id: 'ladder_equal_tee',
        title: 'Cable Ladder 3-Way Equal Tee',
        category: 'Cable Ladders',
        componentType: 'Fittings & Accessories',
        fittingType: 'Tees & Branches',
        subtitle: '90° Equal branch junction (R300)',
        description: '3-way branching assembly with radial curved inner corners and straight rungs.',
        icon: Icons.alt_route,
      ),
      const _GenerativePreset(
        id: 'ladder_equal_cross',
        title: 'Cable Ladder 4-Way Equal Cross',
        category: 'Cable Ladders',
        componentType: 'Fittings & Accessories',
        fittingType: 'Crosses & 4-Ways',
        subtitle: '4-Way intersection junction (R300)',
        description: '4-way cross fitting providing planar cable distribution across four identical ports.',
        icon: Icons.add,
      ),
    ];
    _selectedPreset = _generativePresets.first;
  }

  Future<void> _loadTemplates() async {
    final syncItems = DsfLibraryService.loadAllTemplatesSync();
    if (syncItems.isNotEmpty) {
      if (mounted) {
        setState(() {
          _items = syncItems;
          _isLoading = false;
        });
      }
      return;
    }
    setState(() => _isLoading = true);
    try {
      final items = await DsfLibraryService.loadAllTemplates();
      if (mounted) {
        setState(() {
          _items = items;
          _isLoading = false;
        });
      }
    } catch (e) {
      debugPrint('Error loading template library: $e');
      if (mounted) {
        setState(() => _isLoading = false);
      }
    }
  }

  void _recomputeGenerativeAssembly() {
    final params = LadderAssemblyParameters(
      width: _genWidth,
      height: _genHeight,
      length: _selectedPreset.id == 'ladder_straight' ? _genLength : (_selectedPreset.id == 'ladder_reducer' ? 600.0 : 900.0),
      thickness: _genThickness,
      flangeWidth: _genFlangeWidth,
      flangeDirection: _genFlangeDir,
      jointMethod: _genJointMethod,
      outsideWeldProjection: _genOutsideProjection,
      endMarginPitch: _genEndMarginPitch,
      intermediateTargetPitch: _genCustomPitch ? _genTargetPitch : 300.0,
      accessoryStyle: _genAccessoryStyle,
    );

    switch (_selectedPreset.id) {
      case 'ladder_straight':
        _currentAssembly = LadderAssemblyGenerator.generateStraightLadder(params);
        break;
      case 'ladder_bend_90':
        _currentAssembly = LadderAssemblyGenerator.generateHorizontalBend(
          params: params,
          angleDeg: 90.0,
          radiusMm: _genRadius,
        );
        break;
      case 'ladder_bend_45':
        _currentAssembly = LadderAssemblyGenerator.generateHorizontalBend(
          params: params,
          angleDeg: 45.0,
          radiusMm: _genRadius,
        );
        break;
      case 'ladder_inside_riser_90':
        _currentAssembly = LadderAssemblyGenerator.generateRiser(
          isInsideRiser: true,
          angleDeg: 90.0,
          radiusMm: _genRadius,
          params: params,
        );
        break;
      case 'ladder_outside_riser_90':
        _currentAssembly = LadderAssemblyGenerator.generateRiser(
          isInsideRiser: false,
          angleDeg: 90.0,
          radiusMm: _genRadius,
          params: params,
        );
        break;
      case 'ladder_reducer':
        _currentAssembly = LadderAssemblyGenerator.generateReducer(
          width1: _genWidth,
          width2: _genMinorWidth,
          length: 600.0,
          params: params,
        );
        break;
      case 'ladder_equal_tee':
        _currentAssembly = LadderAssemblyGenerator.generateTee(
          mainWidth: _genWidth,
          branchWidth: _genWidth,
          radiusMm: _genRadius,
          params: params,
        );
        break;
      case 'ladder_equal_cross':
        _currentAssembly = LadderAssemblyGenerator.generateCross(
          mainWidth: _genWidth,
          branchWidth: _genWidth,
          radiusMm: _genRadius,
          params: params,
        );
        break;
      default:
        _currentAssembly = LadderAssemblyGenerator.generateStraightLadder(params);
    }
  }

  // ===========================================================================
  // Filtered Getters
  // ===========================================================================

  List<DsfLibraryItem> get _filteredStoredItems {
    return _items.where((item) {
      // 1. System Category Filter
      if (_selectedSystemCategory != 'All Categories') {
        if (item.systemCategory != _selectedSystemCategory) return false;
      }

      // 2. Component Type Filter (Straight Lengths vs Fittings & Accessories)
      if (_selectedComponentType == 'Straight Lengths') {
        if (item.componentType != 'Length') return false;
      } else if (_selectedComponentType == 'Fittings & Accessories') {
        if (item.componentType != 'Accessory') return false;
        // Sub-filter for specific fitting type
        if (_selectedFittingType != 'All Accessories') {
          if (item.fittingType != _selectedFittingType) return false;
        }
      }

      // 3. Search Query Filter
      if (_searchQuery.isNotEmpty) {
        final query = _searchQuery.toLowerCase();
        final match = item.displayName.toLowerCase().contains(query) ||
            item.fileName.toLowerCase().contains(query) ||
            item.templateId.toLowerCase().contains(query) ||
            item.systemCategory.toLowerCase().contains(query) ||
            item.fittingType.toLowerCase().contains(query) ||
            item.defaultDimensions.toLowerCase().contains(query);
        if (!match) return false;
      }
      return true;
    }).toList();
  }

  List<_GenerativePreset> get _filteredGenerativePresets {
    return _generativePresets.where((preset) {
      // 1. System Category Filter
      if (_selectedSystemCategory != 'All Categories') {
        if (preset.category != _selectedSystemCategory) return false;
      }

      // 2. Component Type Filter
      if (_selectedComponentType != 'All Types') {
        if (preset.componentType != _selectedComponentType) return false;
        if (_selectedComponentType == 'Fittings & Accessories' && _selectedFittingType != 'All Accessories') {
          if (preset.fittingType != _selectedFittingType) return false;
        }
      }

      // 3. Search Query Filter
      if (_searchQuery.isNotEmpty) {
        final query = _searchQuery.toLowerCase();
        final match = preset.title.toLowerCase().contains(query) ||
            preset.subtitle.toLowerCase().contains(query) ||
            preset.description.toLowerCase().contains(query);
        if (!match) return false;
      }
      return true;
    }).toList();
  }

  // ===========================================================================
  // Studio Actions
  // ===========================================================================

  void _handleAddInstance(DsfLibraryItem item, {bool switchToEditor = false}) {
    if (widget.onAddToDds == null) return;

    final baseId = item.templateId.replaceAll('trunking_', '').replaceAll('tray_', '').replaceAll('ladder_', 'lad_');
    final count = (widget.activeDocument?.productInstances.length ?? 0) + 1;
    final productCode = '${baseId.toUpperCase()}-${count.toString().padLeft(3, '0')}';

    final newInstance = DdsProductInstance(
      instanceId: 'inst_${DateTime.now().millisecondsSinceEpoch}_${item.templateId}',
      productName: item.displayName,
      productCode: productCode,
      orderLine: DdsOrderLine(
        lineNumber: count.toString().padLeft(3, '0'),
        customerItemReference: productCode,
        quantity: 1,
        customerDescription: item.description,
      ),
      templateReference: DdsTemplateResolver.createReference(item.templateId),
      instanceParameters: {},
      coverConfiguration: const DdsCoverConfig(
        included: true,
        placementMode3D: 'exploded',
      ),
      material: item.document.material.materialGrade,
      finish: item.document.material.finish.name,
    );

    widget.onAddToDds!(newInstance, switchToEditor: switchToEditor);

    if (switchToEditor) {
      Navigator.of(context).pop();
    } else {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('Added "${item.displayName}" to Technical Data Sheet!'),
          backgroundColor: const Color(0xFF10B981),
          duration: const Duration(seconds: 2),
        ),
      );
    }
  }

  void _openInCadStudio(DsfDocument doc) {
    Navigator.of(context).pop();
    if (widget.onOpenInEditor != null) {
      widget.onOpenInEditor!(doc);
    } else if (widget.viewModel != null) {
      widget.viewModel!.loadDocument(doc);
    }
  }

  void _openGenerativeInCadStudio() {
    if (_currentAssembly == null) return;
    final dsfDoc = LadderAssemblyGenerator.createAssemblyDsfDocument(_currentAssembly!);
    _openInCadStudio(dsfDoc);
  }

  void _addGenerativeToTds() {
    if (widget.onAddToDds == null || _currentAssembly == null) return;
    final dsfDoc = LadderAssemblyGenerator.createAssemblyDsfDocument(_currentAssembly!);
    final item = DsfLibraryItem(
      templateId: _selectedPreset.id,
      displayName: _currentAssembly!.productName,
      fileName: '${_selectedPreset.id}.dsf',
      category: 'Cable Ladders',
      systemCategory: 'Cable Ladders',
      componentType: _selectedPreset.componentType,
      fittingType: _selectedPreset.fittingType,
      description: _selectedPreset.description,
      defaultDimensions: 'W: ${_genWidth.toInt()} mm, H: ${_genHeight.toInt()} mm',
      document: dsfDoc,
      foldedMesh: _currentAssembly!.assembledMesh3D,
      bendCount: _currentAssembly!.rungs.length * 2 + 4,
      punchCount: _currentAssembly!.hardwareBOM.passThroughSlotCount,
      surfaceAreaMm2: (_currentAssembly!.hardwareBOM.totalSteelWeightKg / (_genThickness * 7.85)) * 1000000.0,
      boundWidthMm: _genWidth,
      boundHeightMm: _genLength,
    );
    _handleAddInstance(item, switchToEditor: true);
  }

  Future<void> _saveGenerativeLadderAsDsf() async {
    if (_currentAssembly == null || _isSavingDsf) return;

    final defaultFilename = 'cable_ladder_${_selectedPreset.id.replaceAll('ladder_', '')}_${_genWidth.toInt()}x${_genHeight.toInt()}.dsf';
    final controller = TextEditingController(text: defaultFilename);

    final shouldSave = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E293B),
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(8),
          side: const BorderSide(color: Color(0xFF334155)),
        ),
        title: const Row(
          children: [
            Icon(Icons.save, color: Color(0xFF38BDF8), size: 20),
            SizedBox(width: 8),
            Text(
              'Save to Library as DSF',
              style: TextStyle(color: Color(0xFFF8FAFC), fontSize: 16, fontWeight: FontWeight.bold),
            ),
          ],
        ),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Text(
              'Save this procedural assembly into assets/dsf_templates/ladders/. It will appear permanently in Stored DSF Files.',
              style: TextStyle(color: Color(0xFF94A3B8), fontSize: 12),
            ),
            const SizedBox(height: 14),
            TextField(
              controller: controller,
              style: const TextStyle(color: Color(0xFFF8FAFC), fontSize: 12),
              decoration: InputDecoration(
                labelText: 'DSF Filename',
                labelStyle: const TextStyle(color: Color(0xFF38BDF8), fontSize: 11),
                filled: true,
                fillColor: const Color(0xFF0F172A),
                border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(6),
                  borderSide: const BorderSide(color: Color(0xFF334155)),
                ),
              ),
            ),
          ],
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(ctx).pop(false),
            child: const Text('Cancel', style: TextStyle(color: Color(0xFF94A3B8))),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(backgroundColor: const Color(0xFF0284C7)),
            onPressed: () => Navigator.of(ctx).pop(true),
            child: const Text('Save DSF', style: TextStyle(color: Colors.white)),
          ),
        ],
      ),
    );

    if (shouldSave != true) return;

    setState(() => _isSavingDsf = true);
    try {
      final savedFile = await LadderAssemblyGenerator.saveAssemblyDsfFile(
        _currentAssembly!,
        fileName: controller.text,
      );

      DsfLibraryService.clearCache();
      await _loadTemplates();

      if (mounted) {
        setState(() {
          _isSavingDsf = false;
          _currentTab = DdsLibraryTab.storedDsf;
          _selectedSystemCategory = 'Cable Ladders';
        });

        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('Saved "${savedFile.uri.pathSegments.last}" to Library! Available in Stored DSF Files.'),
            backgroundColor: const Color(0xFF10B981),
            behavior: SnackBarBehavior.floating,
          ),
        );
      }
    } catch (e) {
      if (mounted) {
        setState(() => _isSavingDsf = false);
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('Error saving DSF template: $e'),
            backgroundColor: const Color(0xFFEF4444),
          ),
        );
      }
    }
  }

  // ===========================================================================
  // Build UI
  // ===========================================================================

  @override
  Widget build(BuildContext context) {
    return Container(
      width: 1240,
      height: 800,
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(8.0),
        border: Border.all(color: const Color(0xFFCBD5E1), width: 1.2),
        boxShadow: const [
          BoxShadow(
            color: Colors.black12,
            blurRadius: 24.0,
            offset: Offset(0, 8),
          ),
        ],
      ),
      child: Column(
        children: [
          // 1. Top Header Bar
          _buildHeaderBar(),
          const Divider(height: 1, color: Color(0xFFE2E8F0)),

          // 2. Filter & Search Controls Strip
          _buildFilterStrip(),
          const Divider(height: 1, color: Color(0xFFE2E8F0)),

          // 3. Tab Body
          Expanded(
            child: _currentTab == DdsLibraryTab.storedDsf
                ? (_isLoading ? _buildLoadingState() : _buildTabularView())
                : _buildGenerativeEngineView(),
          ),

          // 4. Bottom Footer Status Bar
          const Divider(height: 1, color: Color(0xFFE2E8F0)),
          _buildFooterBar(),
        ],
      ),
    );
  }

  // ===========================================================================
  // Header Bar
  // ===========================================================================

