        ? '${_filteredStoredItems.length} OF ${_items.length} TEMPLATES STORED'
        : '${_filteredGenerativePresets.length} GENERATIVE PRODUCTS';

    final subtitleText = _currentTab == DdsLibraryTab.storedDsf
        ? 'Standard Cable Management System (CMS) parametric fittings residing in assets/dsf_templates/'
        : 'Procedural Cable Ladder & Fittings Engine (Continuous dual-pitch rung solver, 3D parametric unfolding)';

    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 20.0, vertical: 12.0),
      color: const Color(0xFFF1F5F9),
      child: Row(
        children: [
          Container(
            padding: const EdgeInsets.all(8.0),
            decoration: BoxDecoration(
              color: const Color(0xFFE0F2FE),
              borderRadius: BorderRadius.circular(6.0),
              border: Border.all(color: const Color(0xFFBAE6FD)),
            ),
            child: const Icon(Icons.collections_bookmark, color: Color(0xFF0284C7), size: 20),
          ),
          const SizedBox(width: 12.0),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Wrap(
                  crossAxisAlignment: WrapCrossAlignment.center,
                  spacing: 10.0,
                  children: [
                    const Text(
                      'DSF MASTER TEMPLATE LIBRARY',
                      style: TextStyle(
                        color: Color(0xFF0F172A),
                        fontWeight: FontWeight.bold,
                        fontSize: 14.0,
                        letterSpacing: 0.6,
                      ),
                    ),
                    Container(
                      padding: const EdgeInsets.symmetric(horizontal: 8.0, vertical: 2.0),
                      decoration: BoxDecoration(
                        color: const Color(0xFFE0F2FE),
                        borderRadius: BorderRadius.circular(10.0),
                        border: Border.all(color: const Color(0xFFBAE6FD)),
                      ),
                      child: Text(
                        countText,
                        style: const TextStyle(color: Color(0xFF0369A1), fontSize: 10.0, fontWeight: FontWeight.bold),
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 2.0),
                Text(
                  subtitleText,
                  style: const TextStyle(color: Color(0xFF64748B), fontSize: 11.5),
                ),
              ],
            ),
          ),

          // Primary Tab Switcher
          Container(
            padding: const EdgeInsets.all(3.0),
            decoration: BoxDecoration(
              color: const Color(0xFFE2E8F0),
              borderRadius: BorderRadius.circular(8.0),
              border: Border.all(color: const Color(0xFFCBD5E1)),
            ),
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                _buildTabButton(
                  tab: DdsLibraryTab.storedDsf,
                  icon: Icons.folder,
                  label: 'Stored DSF Files',
                ),
                const SizedBox(width: 4.0),
                _buildTabButton(
                  tab: DdsLibraryTab.autoGenerated,
                  icon: Icons.auto_awesome,
                  label: 'Auto-Generated Products',
                ),
              ],
            ),
          ),
          const SizedBox(width: 12.0),

          // Rescan / Refresh
          IconButton(
            icon: const Icon(Icons.refresh, color: Color(0xFF64748B), size: 20),
            tooltip: 'Re-scan Directory',
            onPressed: () {
              DsfLibraryService.clearCache();
              _loadTemplates();
            },
          ),
          const SizedBox(width: 4.0),
          IconButton(
            icon: const Icon(Icons.close, color: Color(0xFF64748B), size: 20),
            tooltip: 'Close Library',
            onPressed: () => Navigator.of(context).pop(),
          ),
        ],
      ),
    );
  }

  Widget _buildTabButton({
    required DdsLibraryTab tab,
    required IconData icon,
    required String label,
  }) {
    final isSelected = _currentTab == tab;
    return InkWell(
      borderRadius: BorderRadius.circular(6.0),
      onTap: () => setState(() => _currentTab = tab),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 12.0, vertical: 6.0),
        decoration: BoxDecoration(
          color: isSelected ? const Color(0xFF0284C7) : Colors.transparent,
          borderRadius: BorderRadius.circular(6.0),
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(
              icon,
              size: 15,
              color: isSelected ? Colors.white : const Color(0xFF64748B),
            ),
            const SizedBox(width: 6.0),
            Text(
              label,
              style: TextStyle(
                fontSize: 11.5,
                fontWeight: isSelected ? FontWeight.bold : FontWeight.w500,
                color: isSelected ? Colors.white : const Color(0xFF475569),
              ),
            ),
          ],
        ),
      ),
    );
  }

  // ===========================================================================
  // Filter & Search Controls Strip
  // ===========================================================================

  Widget _buildFilterStrip() {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 20.0, vertical: 8.0),
      color: const Color(0xFFF8FAFC),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          // Row 1: Search + Category + Length/Accessories Filter
          SingleChildScrollView(
            scrollDirection: Axis.horizontal,
            child: Row(
              children: [
                // Search Input
                SizedBox(
                  width: 240,
                  height: 34,
                  child: TextField(
                    style: const TextStyle(color: Color(0xFF0F172A), fontSize: 12.0),
                    decoration: InputDecoration(
                      hintText: 'Search templates, ports, sizes...',
                      hintStyle: const TextStyle(color: Color(0xFF94A3B8), fontSize: 11.5),
                      prefixIcon: const Icon(Icons.search, color: Color(0xFF64748B), size: 16),
                      filled: true,
                      fillColor: Colors.white,
                      contentPadding: const EdgeInsets.symmetric(vertical: 0.0, horizontal: 10.0),
                      border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(6.0),
                        borderSide: const BorderSide(color: Color(0xFFCBD5E1)),
                      ),
                      enabledBorder: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(6.0),
                        borderSide: const BorderSide(color: Color(0xFFCBD5E1)),
                      ),
                      focusedBorder: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(6.0),
                        borderSide: const BorderSide(color: Color(0xFF0284C7)),
                      ),
                    ),
                    onChanged: (val) => setState(() => _searchQuery = val),
                  ),
                ),
                const SizedBox(width: 14.0),

                // Category Label & Chips
                const Text('Category:', style: TextStyle(color: Color(0xFF475569), fontSize: 11.5, fontWeight: FontWeight.w600)),
                const SizedBox(width: 8.0),
                Row(
                  children: _systemCategories.map((cat) {
                    final isSelected = _selectedSystemCategory == cat;
                    return Padding(
                      padding: const EdgeInsets.only(right: 6.0),
                      child: ChoiceChip(
                        label: Text(cat, style: TextStyle(fontSize: 11.0, color: isSelected ? Colors.white : const Color(0xFF475569))),
                        selected: isSelected,
                        selectedColor: const Color(0xFF0284C7),
                        backgroundColor: Colors.white,
                        visualDensity: VisualDensity.compact,
                        side: BorderSide(color: isSelected ? const Color(0xFF0284C7) : const Color(0xFFCBD5E1)),
                        onSelected: (selected) {
                          if (selected) setState(() => _selectedSystemCategory = cat);
                        },
                      ),
                    );
                  }).toList(),
                ),

                const SizedBox(width: 12.0),
                Container(width: 1, height: 24, color: const Color(0xFFCBD5E1)),
                const SizedBox(width: 12.0),

                // Component Type (Length vs Accessories)
                const Text('Type:', style: TextStyle(color: Color(0xFF475569), fontSize: 11.5, fontWeight: FontWeight.w600)),
                const SizedBox(width: 8.0),
                Row(
                  children: _componentTypes.map((type) {
                    final isSelected = _selectedComponentType == type;
                    return Padding(
                      padding: const EdgeInsets.only(right: 6.0),
                      child: ChoiceChip(
                        label: Text(type, style: TextStyle(fontSize: 11.0, color: isSelected ? Colors.white : const Color(0xFF475569))),
                        selected: isSelected,
                        selectedColor: const Color(0xFF0284C7),
                        backgroundColor: Colors.white,
                        visualDensity: VisualDensity.compact,
                        side: BorderSide(color: isSelected ? const Color(0xFF0284C7) : const Color(0xFFCBD5E1)),
                        onSelected: (selected) {
                          if (selected) setState(() => _selectedComponentType = type);
                        },
                      ),
                    );
                  }).toList(),
                ),
              ],
            ),
          ),

          // Row 2: Sub-chips for specific fittings (when Fittings & Accessories is active)
          if (_selectedComponentType == 'Fittings & Accessories' || _selectedComponentType == 'All Types') ...[
            const SizedBox(height: 6.0),
            Row(
              children: [
                const SizedBox(width: 4.0),
                const Text('Fittings:', style: TextStyle(color: Color(0xFF64748B), fontSize: 10.5, fontWeight: FontWeight.w500)),
                const SizedBox(width: 8.0),
                Expanded(
                  child: SingleChildScrollView(
                    scrollDirection: Axis.horizontal,
                    child: Row(
                      children: _fittingTypes.map((fit) {
                        final isSelected = _selectedFittingType == fit;
                        return Padding(
                          padding: const EdgeInsets.only(right: 6.0),
                          child: FilterChip(
                            label: Text(fit, style: TextStyle(fontSize: 10.5, color: isSelected ? const Color(0xFF0369A1) : const Color(0xFF475569), fontWeight: isSelected ? FontWeight.bold : FontWeight.normal)),
                            selected: isSelected,
                            selectedColor: const Color(0xFFE0F2FE),
                            backgroundColor: Colors.white,
                            visualDensity: VisualDensity.compact,
                            side: BorderSide(color: isSelected ? const Color(0xFF0284C7) : const Color(0xFFCBD5E1)),
                            onSelected: (selected) {
                              if (selected) setState(() => _selectedFittingType = fit);
                            },
                          ),
                        );
                      }).toList(),
                    ),
                  ),
                ),
              ],
            ),
          ],
        ],
      ),
    );
  }

