  Widget _buildTabularView() {
    final items = _filteredStoredItems;

    if (items.isEmpty) {
      return Center(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            const Icon(Icons.inventory_2_outlined, color: Color(0xFF475569), size: 48),
            const SizedBox(height: 12.0),
            Text(
              'No stored DSF templates found matching current filters.',
              style: const TextStyle(color: Color(0xFF94A3B8), fontSize: 14.0),
            ),
            const SizedBox(height: 8.0),
            TextButton.icon(
              icon: const Icon(Icons.clear_all, size: 16),
              label: const Text('Reset Category Filters'),
              onPressed: () {
                setState(() {
                  _selectedSystemCategory = 'All Categories';
                  _selectedComponentType = 'All Types';
                  _selectedFittingType = 'All Accessories';
                  _searchQuery = '';
                });
              },
            ),
          ],
        ),
      );
    }

    return Column(
      children: [
        // Column Headers
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 20.0, vertical: 8.0),
          color: const Color(0xFFF1F5F9),
          child: const Row(
            children: [
              SizedBox(width: 80, child: Text('2D SKETCH', style: TextStyle(color: Color(0xFF475569), fontSize: 10.5, fontWeight: FontWeight.bold))),
              SizedBox(width: 80, child: Text('3D ISO VIEW', style: TextStyle(color: Color(0xFF475569), fontSize: 10.5, fontWeight: FontWeight.bold))),
              Expanded(flex: 3, child: Text('TEMPLATE / PRODUCT', style: TextStyle(color: Color(0xFF475569), fontSize: 10.5, fontWeight: FontWeight.bold))),
              Expanded(flex: 3, child: Text('BASELINE SPECIFICATION', style: TextStyle(color: Color(0xFF475569), fontSize: 10.5, fontWeight: FontWeight.bold))),
              Expanded(flex: 2, child: Text('GEOMETRY TAKEOFF', style: TextStyle(color: Color(0xFF475569), fontSize: 10.5, fontWeight: FontWeight.bold))),
              SizedBox(width: 260, child: Text('ACTIONS', textAlign: TextAlign.right, style: TextStyle(color: Color(0xFF475569), fontSize: 10.5, fontWeight: FontWeight.bold))),
            ],
          ),
        ),
        const Divider(height: 1, color: Color(0xFFE2E8F0)),

        // Data Rows
        Expanded(
          child: ListView.separated(
