  Widget _buildGenerativeEngineView() {
    final presets = _filteredGenerativePresets;

    return Row(
      children: [
        // Left Column: Presets List
        Container(
          width: 370,
          color: const Color(0xFFF8FAFC),
          padding: const EdgeInsets.all(14.0),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                mainAxisAlignment: MainAxisAlignment.spaceBetween,
                children: [
                  const Text(
                    'GENERATIVE PRESETS',
                    style: TextStyle(color: Color(0xFF334155), fontSize: 11.0, fontWeight: FontWeight.bold, letterSpacing: 0.5),
                  ),
                  Container(
                    padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
                    decoration: BoxDecoration(
                      color: const Color(0xFFE0F2FE),
                      borderRadius: BorderRadius.circular(4),
                      border: Border.all(color: const Color(0xFFBAE6FD)),
                    ),
                    child: Text(
                      '${presets.length} Presets',
                      style: const TextStyle(color: Color(0xFF0369A1), fontSize: 10, fontWeight: FontWeight.bold),
                    ),
                  ),
                ],
              ),
              const SizedBox(height: 4),
              const Text(
                'Engine dynamically synthesizes rails, C-slotted rungs, and welding joints with mathematical precision.',
                style: TextStyle(color: Color(0xFF64748B), fontSize: 10.5),
              ),
              const SizedBox(height: 10),

              // Presets ListView
              Expanded(
                child: presets.isEmpty
                    ? const Center(
                        child: Text(
                          'No presets match current filters.\nSwitch to "Cable Ladders" to view.',
                          textAlign: TextAlign.center,
                          style: TextStyle(color: Color(0xFF64748B), fontSize: 11),
                        ),
                      )
                    : ListView.separated(
                        itemCount: presets.length,
                        separatorBuilder: (_, _) => const SizedBox(height: 6),
                        itemBuilder: (ctx, i) {
                          final preset = presets[i];
                          final isSelected = _selectedPreset.id == preset.id;
                          return GestureDetector(
                            onTap: () {
