        // Right Column: Live Parameter Morphing & Inspector
        Expanded(
          child: _buildGenerativeInspector(),
        ),
      ],
    );
  }

  Widget _buildGenerativeInspector() {
    final assembly = _currentAssembly;
    final bool isPassThrough = _genJointMethod == LadderRungJointMethod.passThroughOutsideWeld;
    final double rungCutLen = assembly != null && assembly.rungs.isNotEmpty
        ? assembly.rungs.first.cutLength
        : (_genWidth + (isPassThrough ? 2 * _genThickness + 2 * _genOutsideProjection : 0.0));
    final bom = assembly?.hardwareBOM;

    return Container(
      padding: const EdgeInsets.all(16.0),
      color: Colors.white,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          // Inspector Header
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    _selectedPreset.title,
                    style: const TextStyle(color: Color(0xFF0F172A), fontSize: 14.0, fontWeight: FontWeight.bold),
                  ),
                  Text(
                    _selectedPreset.subtitle,
                    style: const TextStyle(color: Color(0xFF0284C7), fontSize: 10.5),
                  ),
                ],
              ),
              Row(
                children: [
                  Container(
                    padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                    decoration: BoxDecoration(
                      color: const Color(0xFFDCFCE7),
                      borderRadius: BorderRadius.circular(4),
                      border: Border.all(color: const Color(0xFF86EFAC)),
                    ),
                    child: Text(
                      'Cut Length: ${rungCutLen.toStringAsFixed(1)} mm',
                      style: const TextStyle(color: Color(0xFF15803D), fontSize: 10.5, fontWeight: FontWeight.bold),
                    ),
                  ),
                  const SizedBox(width: 8),
                  IconButton(
                    icon: const Icon(Icons.refresh, size: 16, color: Color(0xFF64748B)),
                    tooltip: 'Reset 3D Orbit Camera',
                    onPressed: () {
                      setState(() {
                        _orbitAzimuth = 45.0;
                        _orbitElevation = 35.264;
                      });
                    },
                  ),
                ],
              ),
            ],
          ),
          const SizedBox(height: 8),

          // Live 3D Assembly Interactive Preview
          Container(
            height: 180,
            decoration: BoxDecoration(
              color: const Color(0xFFF1F5F9),
              borderRadius: BorderRadius.circular(8),
              border: Border.all(color: const Color(0xFFCBD5E1)),
            ),
            clipBehavior: Clip.antiAlias,
            child: GestureDetector(
              onPanUpdate: (details) {
                setState(() {
                  _orbitAzimuth += details.delta.dx * 0.5;
                  _orbitElevation = (_orbitElevation - details.delta.dy * 0.5).clamp(10.0, 85.0);
                });
              },
              child: Stack(
                children: [
                  Positioned.fill(
                    child: CustomPaint(
                      painter: Dds3DIsometricPainter(
                        mesh: assembly?.assembledMesh3D,
                        azimuthDeg: _orbitAzimuth,
                        elevationDeg: _orbitElevation,
                        backgroundColor: const Color(0xFFF1F5F9),
                      ),
                    ),
                  ),
                  Positioned(
                    top: 8,
                    left: 8,
                    child: Container(
                      padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
                      decoration: BoxDecoration(
                        color: Colors.white.withValues(alpha: 0.85),
                        borderRadius: BorderRadius.circular(4),
                        border: Border.all(color: const Color(0xFFCBD5E1)),
                      ),
                      child: const Row(
                        children: [
                          Icon(Icons.touch_app, size: 11, color: Color(0xFF475569)),
                          SizedBox(width: 4),
                          Text('Drag to Orbit 3D Model', style: TextStyle(color: Color(0xFF475569), fontSize: 9.5)),
                        ],
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ),
          const SizedBox(height: 8),

          // Real-time BOM & Geometry Takeoff Banner
          if (bom != null)
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
              decoration: BoxDecoration(
                color: const Color(0xFFF8FAFC),
                borderRadius: BorderRadius.circular(6),
                border: Border.all(color: const Color(0xFFCBD5E1)),
              ),
              child: Wrap(
                spacing: 12.0,
                runSpacing: 4.0,
                alignment: WrapAlignment.spaceBetween,
                children: [
                  Text('Steel Weight: ~${bom.totalSteelWeightKg.toStringAsFixed(2)} kg', style: const TextStyle(color: Color(0xFF0284C7), fontSize: 11, fontWeight: FontWeight.bold)),
                  Text('Rungs: ${bom.rungCount}', style: const TextStyle(color: Color(0xFF0F172A), fontSize: 11, fontWeight: FontWeight.w600)),
                  Text('Punched Slots: ${bom.passThroughSlotCount}', style: const TextStyle(color: Color(0xFF0F172A), fontSize: 11, fontWeight: FontWeight.w600)),
                  Text('Joint: ${isPassThrough ? "Pass-Through Outside Weld" : "Inside Fillet"}', style: const TextStyle(color: Color(0xFF64748B), fontSize: 10.5)),
                ],
              ),
            ),
          const SizedBox(height: 8),

          // Engineering Sliders & Controls
          Expanded(
            child: SingleChildScrollView(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  // Width (W)
                  _buildSliderControl(
                    label: 'LADDER WIDTH (W)',
                    value: _genWidth,
                    min: 150.0,
                    max: 1000.0,
                    unit: 'mm',
                    onChanged: (v) {
                      _genWidth = v;
                      _recomputeGenerativeAssembly();
                    },
                  ),

                  // Rail Height (H)
                  _buildSliderControl(
                    label: 'RAIL HEIGHT (H)',
                    value: _genHeight,
                    min: 50.0,
                    max: 150.0,
                    unit: 'mm',
                    onChanged: (v) {
                      _genHeight = v;
                      _recomputeGenerativeAssembly();
                    },
                  ),

                  // Straight Length (L)
                  if (_selectedPreset.id == 'ladder_straight')
                    _buildSliderControl(
                      label: 'OVERALL LENGTH (L)',
                      value: _genLength,
                      min: 1000.0,
                      max: 6000.0,
                      unit: 'mm',
                      onChanged: (v) {
                        _genLength = v;
                        _recomputeGenerativeAssembly();
                      },
                    ),

                  // Accessory Profile: Angular or Segmented vs Curved
                  if (_selectedPreset.id.contains('bend') || _selectedPreset.id.contains('riser') || _selectedPreset.id.contains('tee') || _selectedPreset.id.contains('cross')) ...[
                    _buildAccessoryStyleSelector(),
                    const SizedBox(height: 12),
                  ],

                  // Radius (for bends / risers / tees / crosses)
                  if (_selectedPreset.id.contains('bend') || _selectedPreset.id.contains('riser') || _selectedPreset.id.contains('tee') || _selectedPreset.id.contains('cross'))
                    _buildSliderControl(
                      label: 'SWEEP / CORNER RADIUS (R)',
                      value: _genRadius,
                      min: 300.0,
                      max: 900.0,
                      unit: 'mm',
                      onChanged: (v) {
                        _genRadius = v;
                        _recomputeGenerativeAssembly();
                      },
                    ),

                  // Reducer Minor Width
                  if (_selectedPreset.id == 'ladder_reducer')
                    _buildSliderControl(
                      label: 'REDUCER MINOR WIDTH (W2)',
                      value: _genMinorWidth,
                      min: 100.0,
                      max: 600.0,
                      unit: 'mm',
                      onChanged: (v) {
                        _genMinorWidth = v;
                        _recomputeGenerativeAssembly();
                      },
                    ),

                  // Sheet Thickness (T)
                  _buildSliderControl(
                    label: 'SHEET THICKNESS (T)',
                    value: _genThickness,
                    min: 1.2,
                    max: 3.0,
                    unit: 'mm',
                    onChanged: (v) {
                      _genThickness = v;
                      _recomputeGenerativeAssembly();
                    },
                  ),

                  // Straight Ladder Rung Pitch Controls
                  if (_selectedPreset.id == 'ladder_straight') ...[
                    Row(
                      mainAxisAlignment: MainAxisAlignment.spaceBetween,
                      children: [
                        const Text(
                          'RUNG PITCH SOLVER',
                          style: TextStyle(color: Color(0xFF475569), fontSize: 10, fontWeight: FontWeight.bold),
                        ),
                        Row(
                          children: [
                            Text(
                              _genCustomPitch ? 'Custom Pitch' : 'Standard 300mm Pitch',
                              style: const TextStyle(color: Color(0xFF0284C7), fontSize: 10),
                            ),
                            Switch(
                              value: _genCustomPitch,
                              activeThumbColor: const Color(0xFF0284C7),
                              onChanged: (val) {
                                setState(() {
                                  _genCustomPitch = val;
                                  _recomputeGenerativeAssembly();
                                });
                              },
                            ),
                          ],
                        ),
                      ],
                    ),
                    if (_genCustomPitch)
                      _buildSliderControl(
                        label: 'TARGET INTERMEDIATE PITCH',
                        value: _genTargetPitch,
                        min: 150.0,
                        max: 500.0,
                        unit: 'mm',
                        onChanged: (v) {
                          _genTargetPitch = v;
                          _recomputeGenerativeAssembly();
                        },
                      ),
                    _buildSliderControl(
                      label: 'END RUN MARGIN (HEADER/FOOTER)',
                      value: _genEndMarginPitch,
                      min: 50.0,
                      max: 250.0,
                      unit: 'mm',
                      onChanged: (v) {
                        _genEndMarginPitch = v;
                        _recomputeGenerativeAssembly();
                      },
                    ),
                  ],

                  // Joint Method
                  Row(
                    mainAxisAlignment: MainAxisAlignment.spaceBetween,
                    children: [
                      const Text(
                        'RUNG-TO-RAIL JOINT METHOD',
                        style: TextStyle(color: Color(0xFF475569), fontSize: 10, fontWeight: FontWeight.bold),
                      ),
                      DropdownButton<LadderRungJointMethod>(
                        value: _genJointMethod,
                        dropdownColor: Colors.white,
                        style: const TextStyle(color: Color(0xFF0F172A), fontSize: 11),
                        underline: const SizedBox(),
                        items: const [
                          DropdownMenuItem(
                            value: LadderRungJointMethod.passThroughOutsideWeld,
                            child: Text('Pass-through Outside Fillet Weld'),
                          ),
                          DropdownMenuItem(
                            value: LadderRungJointMethod.directInsideWeld,
                            child: Text('Direct Inside Fillet Weld'),
                          ),
                        ],
                        onChanged: (val) {
                          if (val != null) {
                            setState(() {
                              _genJointMethod = val;
                              _recomputeGenerativeAssembly();
                            });
                          }
                        },
                      ),
                    ],
                  ),
                ],
              ),
            ),
          ),
          const SizedBox(height: 10),

          // Bottom Action Buttons
          Row(
            mainAxisAlignment: MainAxisAlignment.end,
            children: [
              // Save as DSF in Library
              OutlinedButton.icon(
                style: OutlinedButton.styleFrom(
                  foregroundColor: const Color(0xFF0284C7),
                  side: const BorderSide(color: Color(0xFF0284C7)),
                  padding: const EdgeInsets.symmetric(horizontal: 14.0, vertical: 10.0),
                  shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(6.0)),
                ),
                icon: const Icon(Icons.save, size: 16),
                label: const Text('Save as DSF Template', style: TextStyle(fontSize: 11.5, fontWeight: FontWeight.bold)),
                onPressed: _isSavingDsf ? null : _saveGenerativeLadderAsDsf,
              ),
              const SizedBox(width: 10),

              // Open in CAD Studio
              if (widget.onOpenInEditor != null || widget.viewModel != null)
                ElevatedButton.icon(
                  style: ElevatedButton.styleFrom(
                    backgroundColor: const Color(0xFFF59E0B),
                    foregroundColor: Colors.black,
                    padding: const EdgeInsets.symmetric(horizontal: 16.0, vertical: 10.0),
                    shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(6.0)),
                  ),
                  icon: const Icon(Icons.open_in_new, size: 16),
                  label: const Text('Open in CAD Studio', style: TextStyle(fontSize: 11.5, fontWeight: FontWeight.bold)),
                  onPressed: _openGenerativeInCadStudio,
                ),

              // Add to TDS (if called from TDS)
              if (widget.onAddToDds != null) ...[
                const SizedBox(width: 10),
                ElevatedButton.icon(
                  style: ElevatedButton.styleFrom(
                    backgroundColor: const Color(0xFF0284C7),
                    foregroundColor: Colors.white,
                    padding: const EdgeInsets.symmetric(horizontal: 16.0, vertical: 10.0),
                    shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(6.0)),
                  ),
                  icon: const Icon(Icons.add, size: 16),
                  label: const Text('Add to TDS', style: TextStyle(fontSize: 11.5, fontWeight: FontWeight.bold)),
                  onPressed: _addGenerativeToTds,
                ),
              ],
            ],
          ),
        ],
      ),
    );
  }

  Widget _buildAccessoryStyleSelector() {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Row(
          mainAxisAlignment: MainAxisAlignment.spaceBetween,
          children: [
            const Text(
              'PROFILE / GEOMETRY STYLE',
              style: TextStyle(color: Color(0xFF475569), fontSize: 10, fontWeight: FontWeight.bold),
            ),
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
              decoration: BoxDecoration(
                color: const Color(0xFF0D9488).withValues(alpha: 0.15),
                borderRadius: BorderRadius.circular(4),
              ),
              child: const Text(
                'ISO Standard',
                style: TextStyle(color: Color(0xFF0D9488), fontSize: 9.5, fontWeight: FontWeight.bold),
              ),
            ),
          ],
        ),
        const SizedBox(height: 6),
        Row(
          children: [
            Expanded(
              child: InkWell(
                onTap: () {
                  setState(() {
                    _genAccessoryStyle = LadderAccessoryStyle.segmented;
                    _recomputeGenerativeAssembly();
                  });
                },
                borderRadius: BorderRadius.circular(6),
                child: Container(
                  padding: const EdgeInsets.symmetric(vertical: 7, horizontal: 8),
                  decoration: BoxDecoration(
                    color: _genAccessoryStyle == LadderAccessoryStyle.segmented
                        ? const Color(0xFF0284C7).withValues(alpha: 0.12)
                        : Colors.white,
                    borderRadius: BorderRadius.circular(6),
                    border: Border.all(
                      color: _genAccessoryStyle == LadderAccessoryStyle.segmented
                          ? const Color(0xFF0284C7)
                          : const Color(0xFFCBD5E1),
                      width: _genAccessoryStyle == LadderAccessoryStyle.segmented ? 1.5 : 1.0,
                    ),
                  ),
                  child: Row(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      Icon(
                        Icons.architecture,
                        size: 14,
                        color: _genAccessoryStyle == LadderAccessoryStyle.segmented
                            ? const Color(0xFF0284C7)
                            : const Color(0xFF64748B),
                      ),
                      const SizedBox(width: 4),
                      Text(
                        'Angular / Segmented',
                        style: TextStyle(
                          fontSize: 10.5,
                          fontWeight: _genAccessoryStyle == LadderAccessoryStyle.segmented
                              ? FontWeight.bold
                              : FontWeight.w500,
                          color: _genAccessoryStyle == LadderAccessoryStyle.segmented
                              ? const Color(0xFF0284C7)
                              : const Color(0xFF334155),
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ),
            const SizedBox(width: 6),
            Expanded(
              child: InkWell(
                onTap: () {
                  setState(() {
                    _genAccessoryStyle = LadderAccessoryStyle.curved;
                    _recomputeGenerativeAssembly();
                  });
                },
                borderRadius: BorderRadius.circular(6),
                child: Container(
                  padding: const EdgeInsets.symmetric(vertical: 7, horizontal: 8),
                  decoration: BoxDecoration(
                    color: _genAccessoryStyle == LadderAccessoryStyle.curved
                        ? const Color(0xFF0284C7).withValues(alpha: 0.12)
                        : Colors.white,
                    borderRadius: BorderRadius.circular(6),
                    border: Border.all(
                      color: _genAccessoryStyle == LadderAccessoryStyle.curved
                          ? const Color(0xFF0284C7)
                          : const Color(0xFFCBD5E1),
                      width: _genAccessoryStyle == LadderAccessoryStyle.curved ? 1.5 : 1.0,
                    ),
                  ),
                  child: Row(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      Icon(
                        Icons.rounded_corner,
                        size: 14,
                        color: _genAccessoryStyle == LadderAccessoryStyle.curved
                            ? const Color(0xFF0284C7)
                            : const Color(0xFF64748B),
                      ),
                      const SizedBox(width: 4),
                      Text(
                        'Curved (Smooth)',
                        style: TextStyle(
                          fontSize: 10.5,
                          fontWeight: _genAccessoryStyle == LadderAccessoryStyle.curved
                              ? FontWeight.bold
                              : FontWeight.w500,
                          color: _genAccessoryStyle == LadderAccessoryStyle.curved
                              ? const Color(0xFF0284C7)
                              : const Color(0xFF334155),
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ),
          ],
        ),
      ],
    );
  }

  Widget _buildSliderControl({
    required String label,
    required double value,
    required double min,
    required double max,
    required String unit,
    required ValueChanged<double> onChanged,
  }) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 6.0),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Text(
                label,
                style: const TextStyle(color: Color(0xFF475569), fontSize: 10.0, fontWeight: FontWeight.w600),
              ),
              Text(
                '${value.toStringAsFixed(value == value.roundToDouble() ? 0 : 1)} $unit',
                style: const TextStyle(color: Color(0xFF0284C7), fontSize: 11.0, fontWeight: FontWeight.bold),
              ),
            ],
          ),
          SliderTheme(
            data: SliderTheme.of(context).copyWith(
              trackHeight: 3.0,
              thumbShape: const RoundSliderThumbShape(enabledThumbRadius: 6.0),
              overlayShape: const RoundSliderOverlayShape(overlayRadius: 12.0),
              activeTrackColor: const Color(0xFF0284C7),
              inactiveTrackColor: const Color(0xFFE2E8F0),
              thumbColor: const Color(0xFF0284C7),
            ),
            child: Slider(
              value: value.clamp(min, max),
              min: min,
              max: max,
              onChanged: (v) => setState(() => onChanged(v)),
            ),
          ),
        ],
      ),
    );
  }

  // ===========================================================================
  // Loading & Footer States
  // ===========================================================================

  Widget _buildLoadingState() {
    return const Center(
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          CircularProgressIndicator(strokeWidth: 2.5, color: Color(0xFF0284C7)),
          SizedBox(height: 16.0),
          Text(
            'Scanning App Directory & Inspecting DSF Templates...',
            style: TextStyle(color: Color(0xFF64748B), fontSize: 13.0),
          ),
        ],
      ),
    );
  }

  Widget _buildFooterBar() {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 20.0, vertical: 10.0),
      color: const Color(0xFFF1F5F9),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          Text(
            _currentTab == DdsLibraryTab.storedDsf
                ? 'Showing ${_filteredStoredItems.length} of ${_items.length} stored templates • Base: assets/dsf_templates/'
                : 'Procedural CMS Engine • Dual-pitch continuous rung placement with 3D kinematic unfolding',
            style: const TextStyle(color: Color(0xFF64748B), fontSize: 11.5),
          ),
          TextButton(
            style: TextButton.styleFrom(
              foregroundColor: const Color(0xFF0284C7),
              padding: const EdgeInsets.symmetric(horizontal: 16.0, vertical: 8.0),
            ),
            child: const Text('Done', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 12.5)),
            onPressed: () => Navigator.of(context).pop(),
          ),
        ],
      ),
    );
  }
}
